import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Resources/app_colors.dart';import '../../../../../../Config/Routes/route_name.dart';import '../../../../../../Core/Models/cart_itemes.dart';import '../../../../../../Core/Utils/Widget/Images/build_image.dart';import '../../../../../../generated/l10n.dart';import '../../../../../../main.dart';class BodyPageCartItems extends StatelessWidget {  const BodyPageCartItems(      {super.key, required this.cartItems, required this.local});  final List<Item>? cartItems;  final S local;  @override  Widget build(BuildContext context) {    return ListView(children: [      ...List.generate(cartItems?.length ?? 0, (index) {        final items = cartItems?[index];        final product = items?.product;        return GestureDetector(          onTap: () {            kNavigationService.navigateTo(AppRoutes.productDetails,                arguments: product?.id);          },          child: Card(            margin: REdgeInsets.all(15),            child: Padding(              padding: const EdgeInsets.all(8.0),              child: Row(                children: [                  BuildImageAssets(                    url:                        "https://moccasin-manatee-172732.hostingersite.com/storage/products/1742696471_67df7017d7922.jpg",                    width: 150.w,                    height: 150.h,                  ),                  SizedBox(                      width: .3.sw,                      child: Column(                        crossAxisAlignment: CrossAxisAlignment.start,                        children: [                          Text(product?.name ?? ""),                          Text(product?.price.toString() ?? ""),                          Text(                            "${local.Color}: ${items?.color?.name ?? ""}",                            // style: AppTextStyles.bodySmall,                          ),                          Text(                            "${local.Size}: ${items?.size?.name ?? ""}",                            // style: AppTextStyles.bodySmall,                          ),                        ],                      )),                  Container(                    color: AppColors.primaryColor.withAlpha(100),                    height: 120.h,                    width: 1.w,                  ),                  Expanded(                      child: Column(                    mainAxisAlignment: MainAxisAlignment.center,                    children: [                      Text(items!.quantity.toString()),                      20.verticalSpace,                      Row(                        mainAxisAlignment: MainAxisAlignment.center,                        children: [                          Icon(Icons.remove_circle),                          20.horizontalSpace,                          Icon(Icons.add_circle),                        ],                      )                    ],                  ))                ],              ),            ),          ),        );      }),    ]);  }}